// messaging.ts

import * as twilio from 'twilio';
import * as dotenv from 'dotenv';

// Load environment variables
dotenv.config();

// Define types for different recipient formats
type EmailRecipient = {
  type: 'email';
  address: string;
  name?: string;
};

type PhoneRecipient = {
  type: 'phone';
  number: string;
  name?: string;
  carrier?: string; // Optional carrier information for SMS gateway
};

// Union type for all recipient formats
type Recipient = EmailRecipient | PhoneRecipient;

// Initialize Twilio client
const twilioClient = twilio(
  process.env.TWILIO_ACCOUNT_SID,
  process.env.TWILIO_AUTH_TOKEN
);

const twilioPhoneNumber = process.env.TWILIO_PHONE_NUMBER;

/**
 * Send a message to one or more recipients
 * 
 * @param recipients - Single recipient or array of recipients
 * @param message - Message to send to all recipients
 * @param subject - Optional subject line for email messages
 * @returns Promise that resolves when all messages are sent
 */
async function sendMessage(
  recipients: Recipient | Recipient[],
  message: string,
  subject?: string
): Promise<boolean> {
  // Convert single recipient to array for consistent handling
  const recipientArray = Array.isArray(recipients) ? recipients : [recipients];

  try {
    // Send to each recipient in parallel
    const results = await Promise.all(
      recipientArray.map(recipient => {
        if (recipient.type === 'email') {
          return sendEmail(recipient, message, subject);
        } else if (recipient.type === 'phone') {
          return sendSMS(recipient, message);
        } else {
          // Type checking to ensure we handle all possible types
          const _exhaustiveCheck: never = recipient;
          throw new Error(`Unsupported recipient type: ${(recipient as any).type}`);
        }
      })
    );

    // Return true if all messages were sent successfully
    return results.every(result => result === true);
  } catch (error) {
    console.error('Error sending messages:', error);
    return false;
  }
}

/**
 * Send an email to a recipient
 * 
 * @param recipient - Email recipient details
 * @param message - Message content
 * @param subject - Optional subject line
 * @returns Promise that resolves to true if sent successfully
 */
async function sendEmail(
  recipient: EmailRecipient,
  message: string,
  subject?: string
): Promise<boolean> {
  // Implementation placeholder - would use an email service
  console.log(`Sending email to ${recipient.address}${recipient.name ? ` (${recipient.name})` : ''}`);
  console.log(`Subject: ${subject || 'No subject'}`);
  console.log(`Message: ${message}`);

  // Actual implementation would go here
  return true; // Mock successful sending
}

/**
 * Send an SMS to a recipient using Twilio
 * 
 * @param recipient - Phone recipient details
 * @param message - Message content
 * @returns Promise that resolves to true if sent successfully
 */
async function sendSMS(
  recipient: PhoneRecipient, 
  message: string
): Promise<boolean> {
  try {
    if (!twilioClient || !twilioPhoneNumber) {
      throw new Error('Twilio credentials not properly configured');
    }

    // Log attempt (helpful for debugging)
    console.log(`Sending SMS to ${recipient.number}${recipient.name ? ` (${recipient.name})` : ''}`);

    // Format the phone number to E.164 format if it's not already
    const formattedNumber = formatPhoneNumber(recipient.number);

    // Send the SMS using Twilio
    const twilioMessage = await twilioClient.messages.create({
      body: message,
      from: twilioPhoneNumber,
      to: formattedNumber
    });

    console.log(`SMS sent successfully. SID: ${twilioMessage.sid}`);
    return true;

  } catch (error) {
    console.error(`Error sending SMS to ${recipient.number}:`, error);
    return false;
  }
}

/**
 * Format a phone number to E.164 format for Twilio
 * 
 * @param phoneNumber - The phone number to format
 * @returns The formatted phone number
 */
function formatPhoneNumber(phoneNumber: string): string {
  // Remove any non-digit characters
  const digitsOnly = phoneNumber.replace(/\D/g, '');

  // Check if the number already has a country code
  if (digitsOnly.startsWith('1') && digitsOnly.length === 11) {
    return `+${digitsOnly}`;
  } 

  // Assume US/Canada number and add +1 if 10 digits
  if (digitsOnly.length === 10) {
    return `+1${digitsOnly}`;
  }

  // If already has + prefix, just return it
  if (phoneNumber.startsWith('+')) {
    return phoneNumber;
  }

  // For any other format, just add + prefix
  return `+${digitsOnly}`;
}

// Example usage
async function main() {
  const message = "Hello! This is a test message sent via Twilio.";

  const recipient: PhoneRecipient = { 
    type: 'phone', 
    number: '5551234567', // This will be formatted to +15551234567
    name: 'Test User' 
  };

  // Send a test SMS
  const success = await sendSMS(recipient, message);

  if (success) {
    console.log("SMS sent successfully!");
  } else {
    console.log("Failed to send SMS.");
  }
}

